'use client'

import type { ReactNode } from 'react'

interface CompactBarProps {
  price: string
  rating: string
  onReserve?: () => void
  onPhotos?: () => void
}

/**
 * CompactBar — shown in the navbar when the user has scrolled past the photo grid.
 * Contains section tab links and a quick reserve CTA matching reference site.
 */
export function CompactBar({ price, rating, onReserve, onPhotos }: CompactBarProps): ReactNode {
  return (
    <>
      <div className="section-tabs" role="navigation" aria-label="Page sections">
        <button className="active" onClick={onPhotos}>Photos</button>
        <a href="#amenities">Amenities</a>
        <a href="#reviews">Reviews</a>
        <a href="#location">Location</a>
      </div>
      <div className="compact-cta">
        <div>
          <strong>{price}</strong>
          <span> · ★ {rating} · 19 reviews</span>
        </div>
        <button onClick={onReserve} aria-label="Reserve this listing">Reserve</button>
      </div>
    </>
  )
}
