'use client'

import type { ReactNode } from 'react'
import { Header } from '@/components/header'
import { CompactBar } from './CompactBar'

interface NavbarProps {
  compact: boolean
  price: string
  rating: string
  onScrollToPhotos: () => void
}

/**
 * Navbar — handles switching between the reconstructed Desktop Header
 * (in default mode) and the CompactBar (when scrolled past photos).
 */
export function Navbar({ compact, price, rating, onScrollToPhotos }: NavbarProps): ReactNode {
  if (!compact) {
    return <Header onScrollToTop={onScrollToPhotos} />
  }

  return (
    <header className="topbar compact" role="banner">
      <div className="nav-inner">
        <button
          className="brand"
          onClick={onScrollToPhotos}
          aria-label="Airbnb — scroll to top"
        >
          <img
            src="/airbnb-logo.png"
            alt="Airbnb"
            style={{ height: '28px', width: 'auto', objectFit: 'contain' }}
          />
        </button>

        <CompactBar
          price={price}
          rating={rating}
          onPhotos={onScrollToPhotos}
        />
      </div>
    </header>
  )
}
