'use client'

import type { ReactNode } from 'react'
import type { Review } from '../../types'
import { ReviewCard } from './ReviewCard'
import { RatingBars } from './RatingBars'
import { REVIEW_TAGS } from '../../constants/mock-data'

interface ReviewsSectionProps {
  reviews: Review[]
  totalCount: number
  onShowAll: () => void
}

/**
 * ReviewsSection — full reviews section matching reference site.
 * Large centered rating mark with leaf emoji, guest favourite badge,
 * rating categories grid, filter tags, and review cards.
 */
export function ReviewsSection({ reviews, totalCount, onShowAll }: ReviewsSectionProps): ReactNode {
  return (
    <section id="reviews" className="content-section" aria-labelledby="reviews-heading">
      {/* Large centered rating display */}
      <div className="rating-mark" aria-label="Overall rating: 4.95">
        <div className="rating-mark-emoji" aria-hidden="true">
          🏆 <strong>4.95</strong> 🏆
        </div>
        <span className="rating-mark-title">Guest favourite</span>
        <small>This home is a guest favourite based on ratings, reviews and reliability</small>
        <a href="#" aria-label="Learn how reviews work">How reviews work</a>
      </div>

      {/* Section title row */}
      <div className="section-title-row">
        <div>
          <h2 id="reviews-heading">{totalCount} reviews</h2>
        </div>
      </div>

      {/* Rating bars and category scores */}
      <RatingBars />

      {/* Review filter tags / pills */}
      <div className="tags" role="list" aria-label="Guest review highlights">
        {REVIEW_TAGS.map((tag) => (
          <span key={tag} role="listitem">{tag}</span>
        ))}
      </div>

      {/* Review cards grid */}
      <div className="review-grid">
        {reviews.map((review) => (
          <ReviewCard key={review.name} review={review} />
        ))}
      </div>

      <button className="outline-btn" onClick={onShowAll}>
        Show all {totalCount} reviews
      </button>
    </section>
  )
}
