'use client'

import type { ReactNode } from 'react'
import { Logo } from './Logo'
import { SearchBar } from './SearchBar'
import { HeaderActions } from './HeaderActions'

interface HeaderProps {
  onScrollToTop?: () => void
  onSearch?: () => void
  onBecomeHost?: () => void
  onLanguageSelect?: () => void
  onLogin?: () => void
  onSignUp?: () => void
}

/**
 * Header — the reconstructed desktop Airbnb header matching reference screenshot.
 * Exact 80px height, #EBEBEB bottom border, centered search bar, 80px padding.
 */
export function Header({
  onScrollToTop,
  onSearch,
  onBecomeHost,
  onLanguageSelect,
  onLogin,
  onSignUp,
}: HeaderProps): ReactNode {
  return (
    <header role="banner" className="desktop-header">
      <div className="desktop-header-inner">
        {/* Left Column: Logo */}
        <div className="desktop-header-left">
          <Logo onScrollToTop={onScrollToTop} />
        </div>

        {/* Center Column: Perfectly Centered SearchBar */}
        <div className="desktop-header-center">
          <SearchBar onSearch={onSearch} />
        </div>

        {/* Right Column: Actions & Profile Menu */}
        <div className="desktop-header-right">
          <HeaderActions
            onBecomeHost={onBecomeHost}
            onLanguageSelect={onLanguageSelect}
            onLogin={onLogin}
            onSignUp={onSignUp}
          />
        </div>
      </div>
    </header>
  )
}
