import type { ReactNode } from 'react'
import type { Review } from '../../types'

interface ReviewCardProps {
  review: Review
}

/**
 * ReviewCard — a single guest review in the reviews grid.
 * Matches reference site with avatar, name, date, star rating, and review text.
 */
export function ReviewCard({ review }: ReviewCardProps): ReactNode {
  return (
    <article className="review">
      <div className="review-header">
        <div
          className="avatar"
          aria-label={`${review.name}'s avatar`}
          role="img"
        >
          {review.initial}
        </div>
        <div>
          <b>{review.name}</b>
          <small>{review.when}</small>
        </div>
      </div>
      <div className="review-stars" aria-label={`Rating: ${review.score} stars`}>
        {'★'.repeat(Math.round(parseFloat(String(review.score))))}
        <span style={{ marginLeft: '4px', fontSize: '13px', color: '#717171' }}>
          {review.when}
        </span>
      </div>
      <p>{review.text}</p>
      <a href="#" aria-label={`Show more from ${review.name}`}>Show more</a>
    </article>
  )
}
