import type { ReactNode } from 'react'
import { getRatingBarWidth } from '../../utils/formatting'
import { RATING_CATEGORIES } from '../../constants/mock-data'
import { Sparkles, CircleCheckBig, Search, MessageCircle, Map, Tag } from 'lucide-react'

/**
 * RatingBars — overall rating bar chart and per-category scores.
 * Matches reference site: horizontal layout with bars + 6 category columns.
 */
export function RatingBars(): ReactNode {
  const starCounts = [5, 4, 3, 2, 1]

  const categoryIcons: Record<string, ReactNode> = {
    Cleanliness: <Sparkles size={28} strokeWidth={1.5} className="cat-icon" />,
    Accuracy: <CircleCheckBig size={28} strokeWidth={1.5} className="cat-icon" />,
    'Check-in': <Search size={28} strokeWidth={1.5} className="cat-icon" />,
    Communication: <MessageCircle size={28} strokeWidth={1.5} className="cat-icon" />,
    Location: <Map size={28} strokeWidth={1.5} className="cat-icon" />,
    Value: <Tag size={28} strokeWidth={1.5} className="cat-icon" />,
  }

  return (
    <div className="rating-cats-grid" aria-label="Rating breakdown">
      {/* Overall rating column with bar chart */}
      <div className="bars" aria-label="Overall rating distribution">
        <p className="bars-title">Overall rating</p>
        {starCounts.map((n) => (
          <div key={n}>
            <small>{n}</small>
            <i aria-label={`${n} star bar`}>
              <em style={{ width: getRatingBarWidth(n) }} />
            </i>
          </div>
        ))}
      </div>

      {/* 6 category columns */}
      {RATING_CATEGORIES.map(({ name, score }) => (
        <div className="rating-cat-item" key={name}>
          <span className="cat-title">{name}</span>
          <span className="cat-score">{score}</span>
          {categoryIcons[name] ?? null}
        </div>
      ))}
    </div>
  )
}
